// ── VALIDATE & NORMALIZE ──────────────────────────────────────────────────
const body = $json.body ?? $json;

const missing = ['itemId', 'studyUnitId'].filter(f => !body[f]);
if (missing.length > 0) {
  throw new Error(JSON.stringify({
    error: 'Missing required fields',
    missing,
    received: Object.keys(body)
  }));
}

const today = new Date().toISOString().slice(0, 10);
const fileName = body.fileName ?? `${body.studyUnitId}_mcqs_${today}.xlsx`;

// PATH A: pre-built base64 file from Claude Code
if (body.file_base64) {
  return [{
    json: {
      path:        'A',
      itemId:      String(body.itemId),
      studyUnitId: body.studyUnitId,
      sessionId:   body.sessionId ?? '',
      fileName,
      mimeType:    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      fileBase64:  body.file_base64,
      rowCount:    null
    }
  }];
}

// PATH B: MCQ JSON array
if (!body.mcqs || !Array.isArray(body.mcqs) || body.mcqs.length === 0) {
  throw new Error(JSON.stringify({
    error: 'Payload must include file_base64 (Path A) or a non-empty mcqs array (Path B)',
    received: Object.keys(body)
  }));
}

const mcqRows = body.mcqs.map((q, i) => ({
  '#':              i + 1,
  'Question':       q.question_text  ?? q.question  ?? '',
  'Choice A':       q.choice_a       ?? q.option_a  ?? '',
  'Choice B':       q.choice_b       ?? q.option_b  ?? '',
  'Choice C':       q.choice_c       ?? q.option_c  ?? '',
  'Choice D':       q.choice_d       ?? q.option_d  ?? '',
  'Correct Answer': q.correct_answer ?? 'A',
  'Explanation':    q.explanation    ?? '',
  'Bloom Level':    q.bloom_level    ?? '',
  'Topic':          q.topic          ?? '',
  'Study Unit':     q.study_unit     ?? body.studyUnitId ?? ''
}));

return [{
  json: {
    path:        'B',
    itemId:      String(body.itemId),
    studyUnitId: body.studyUnitId,
    sessionId:   body.sessionId ?? '',
    fileName,
    rowCount:    mcqRows.length,
    mcqRows
  }
}];

// ── BUILD CSV (Path B only) ────────────────────────────────────────────────
// Pure JavaScript CSV generation — no npm packages or community nodes needed.

const { itemId, studyUnitId, sessionId, fileName, rowCount, mcqRows } = $json;

const headers = [
  '#', 'Question', 'Choice A', 'Choice B', 'Choice C', 'Choice D',
  'Correct Answer', 'Explanation', 'Bloom Level', 'Topic', 'Study Unit'
];

const csvEscape = (val) => {
  const str = String(val ?? '');
  if (str.includes(',') || str.includes('"') || str.includes('\n') || str.includes('\r')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
};

const csvLines = [
  headers.map(csvEscape).join(','),
  ...mcqRows.map(row => headers.map(h => csvEscape(row[h])).join(','))
];

const csvString = csvLines.join('\r\n');
const csvFileName = fileName.replace(/\.xlsx$/i, '.csv');

return [{
  json: {
    itemId,
    studyUnitId,
    sessionId,
    fileName:   csvFileName,
    mimeType:   'text/csv',
    rowCount,
    fileBase64: Buffer.from(csvString, 'utf8').toString('base64')
  }
}];

// ── PREPARE UPLOAD ────────────────────────────────────────────────────────
// Converts base64 file into n8n binary format so the HTTP Request node
// can send it as multipart/form-data.
// Also builds the GraphQL mutation query and map strings.

const { itemId, studyUnitId, sessionId, fileName, mimeType, rowCount, fileBase64 } = $json;

const contentType = mimeType ??
  (fileName.endsWith('.csv')
    ? 'text/csv'
    : 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');

const mutation = `mutation ($file: File!) {
  add_file_to_column(
    item_id: ${itemId},
    column_id: "file_mm0vtzzb",
    file: $file
  ) { id }
}`;

return [{
  json: {
    itemId,
    studyUnitId,
    sessionId,
    fileName,
    rowCount:  rowCount ?? 'n/a',
    query:     mutation,
    map:       '{"0": ["variables.file"]}'
  },
  binary: {
    file: {
      data:     fileBase64,
      mimeType: contentType,
      fileName: fileName
    }
  }
}];

